// CGM Lab Assignment 2 - DDA Line Drawing Algorithm
// Uses FreeGLUT / OpenGL. Menu-driven program with switch-case.

#include <GL/freeglut.h>
#include <iostream>
#include <algorithm>
#include <cmath>

using namespace std;

float x1p, y1p, x2p, y2p;
float xIncrement, yIncrement;
int numberOfSteps;

void display() {
    glClear(GL_COLOR_BUFFER_BIT);
    glColor3f(0.0f, 0.0f, 0.0f);
    glPointSize(4.0f);

    // Plot every intermediate point generated by the DDA algorithm.
    glBegin(GL_POINTS);
    float x = x1p;
    float y = y1p;

    if (numberOfSteps == 0) {
        glVertex2f(x, y);
    } else {
        for (int i = 0; i <= numberOfSteps; ++i) {
            glVertex2f(round(x), round(y));
            x += xIncrement;
            y += yIncrement;
        }
    }
    glEnd();
    glFlush();
}

int main(int argc, char** argv) {
    int menuChoice;

    cout << "\n===== CGM LAB ASSIGNMENT 2 =====\n";
    cout << "DDA LINE DRAWING ALGORITHM\n";
    cout << "1. Draw a line using DDA Algorithm\n";
    cout << "2. Exit\n";
    cout << "Enter your choice: ";

    if (!(cin >> menuChoice)) {
        cout << "Invalid input.\n";
        return 1;
    }

    // switch-case implements the required menu.
    switch (menuChoice) {
        case 1: {
            cout << "Enter starting point (x1 y1): ";
            cin >> x1p >> y1p;
            cout << "Enter ending point (x2 y2): ";
            cin >> x2p >> y2p;

            float dx = x2p - x1p;
            float dy = y2p - y1p;
            numberOfSteps = static_cast<int>(max(fabs(dx), fabs(dy)));

            if (numberOfSteps == 0) {
                xIncrement = 0.0f;
                yIncrement = 0.0f;
            } else {
                xIncrement = dx / numberOfSteps;
                yIncrement = dy / numberOfSteps;
            }

            cout << "\n dx = " << dx << "\n dy = " << dy;
            cout << "\n steps = " << numberOfSteps;
            cout << "\n x increment = " << xIncrement;
            cout << "\n y increment = " << yIncrement << "\n";

            break;
        }
        case 2:
            cout << "Program exited.\n";
            return 0;
        default:
            cout << "Invalid menu choice.\n";
            return 1;
    }

    glutInit(&argc, argv);
    glutInitDisplayMode(GLUT_SINGLE | GLUT_RGB);
    glutInitWindowSize(700, 550);
    glutInitWindowPosition(100, 100);
    glutCreateWindow("CGM Lab 2 - DDA Line Drawing Algorithm");

    glClearColor(1.0f, 1.0f, 1.0f, 1.0f);
    glMatrixMode(GL_PROJECTION);
    glLoadIdentity();

    float minX = min(x1p, x2p);
    float maxX = max(x1p, x2p);
    float minY = min(y1p, y2p);
    float maxY = max(y1p, y2p);
    float margin = max(10.0f, max(maxX - minX, maxY - minY) * 0.15f);

    if (minX == maxX) { minX -= margin; maxX += margin; }
    if (minY == maxY) { minY -= margin; maxY += margin; }

    gluOrtho2D(minX - margin, maxX + margin,
               minY - margin, maxY + margin);

    glutDisplayFunc(display);
    glutMainLoop();
    return 0;
}
